'ism.h_doc' => 'The documented information of the ISMS: policies, procedures and records, each with its version, approval and next review. The list starts with what ISO/IEC 27001:2022 asks for; attach the approved file to each.',
'ism.h_risk' => 'Risk assessment and treatment: what could go wrong, how likely and how bad (1–5 each), what is done about it and what remains afterwards.',
'ism.h_soa' => 'The 93 controls of Annex A. For each: does it apply (if not, why), how far it is implemented and how — with the evidence attached.',
'ism.h_asset' => 'Inventory of information and the assets that hold it: equipment, software, information, services, sites.',
'ism.h_incident' => 'Security events and incidents: what happened, how it was contained, the cause and what was learned. Reports from staff arrive here as “Reported”.',
'ism.h_audit' => 'The programme of internal audits, management reviews and periodic checks (access reviews, restore tests, continuity exercises) with their results and reports.',
'ism.h_nc' => 'Nonconformities and corrective actions: what was found, its cause, the correction, the action against recurrence and whether it worked.',
'ism.h_objective' => 'Information security objectives and how they are measured: target, result and date.',
'ism.h_supplier' => 'Suppliers that handle our information or systems: the service, what they can reach, the agreement and when they were last reviewed.',
'ism.h_training' => 'Awareness and training sessions: topic, audience, date and the evidence of attendance.',
'ism.h_legal' => 'Laws, regulations and contract terms on information security that apply to us, and how each is met.',
'ism.lv_critical' => 'critical',
'ism.k_risks_s4' => 'critical {c} · high {h} · medium {m} · low {l} · not scored {u}',
'ism.score_hint_matrix' => 'level from the risk matrix of the Risk Assessment & Treatment Methodology (ISMS-TIER1-004): Low · Medium · High · Critical. An impact of 5 is at least High, and Critical from likelihood 3. Low: accepted by the risk owner. Medium: reviewed and approved by the IT Manager. High: treated as a rule; accepted only with justification by the risk owner and the IT Manager, and reported to the management review. Critical: treated, or escalated to management for acceptance.',
