'pf.sb' => 'System Budget',
'pf.sb_w' => 'Sales · project managers',
'pf.sb_q' => 'Parts and working hours of the system are estimated line by line. Nothing is reserved or ordered.',
'pf.sb_m' => 'Internal estimate: cost of parts and labour, sale price and margin. Not yet a commitment to anyone.',
'pf.offer' => 'Offer to the customer',
'pf.offer_w' => 'Sales',
'pf.offer_q' => 'The scope offered, with its quantities.',
'pf.offer_m' => 'Offer value and payment terms. It counts in the pipeline, not yet as an order.',
'pf.approved' => 'Offer approved by the customer',
'pf.approved_w' => 'Sales · project manager',
'pf.approved_q' => 'The project and its sub-projects carry the work. The hours and parts of the offer become the budget of the sub-project.',
'pf.approved_m' => 'The order value is fixed. The parts budget of the sub-project is the limit Purchasing is measured against. A proforma can be issued for each payment term.',
'pf.bom' => 'Bill of materials (BOM)',
'pf.bom_w' => 'Engineering — approved before buying',
'pf.bom_q' => 'What the system needs, item by item, by revision. Lines are matched to the inventory by our code or the maker part number; new items get their code from Procurement.',
'pf.bom_m' => 'Estimated at the prices known in the inventory. No money is committed.',
'pf.req' => 'Requisition',
'pf.req_w' => 'Requested by the project · approved by management',
'pf.req_q' => 'Quantity requested, from the BOM or typed. On approval, what is free in the warehouse is reserved for the requisition; the rest is "to buy".',
'pf.req_m' => 'Estimated value against the parts budget of the sub-project: budget, already committed, actual — and a mark when it goes over.',
'pf.rfq' => 'Request for quotation (optional)',
'pf.rfq_w' => 'Procurement',
'pf.rfq_q' => 'The quantities asked from one or more suppliers. Nothing is ordered yet.',
'pf.rfq_m' => 'Prices and lead times quoted by the supplier — typed, or read from his offer by the assistant. The awarded quotation becomes the order.',
'pf.po' => 'Purchase order',
'pf.po_w' => 'Procurement — sent to the supplier',
'pf.po_q' => 'Quantity ordered per line. When the order is sent, the requisition line shows it as ordered.',
'pf.po_m' => 'Unit price, discount and VAT give the order total: money committed to the supplier, counted against the budget of the sub-project.',
'pf.receipt' => 'Receipt of goods',
'pf.receipt_w' => 'Warehouse — incoming inspection',
'pf.receipt_q' => 'Received, accepted and rejected per line (a rejection opens a non-conformity). Accepted goods enter the stock of the warehouse and are reserved for the requisition they were bought for.',
'pf.receipt_m' => 'The goods enter at the price of the order: it becomes the last buying price of the item and the value of the stock.',
'pf.issue' => 'Issue to the project',
'pf.issue_w' => 'Warehouse',
'pf.issue_q' => 'The quantity issued leaves the stock; the reservation is released and the requisition line shows it as issued.',
'pf.issue_m' => 'The movement carries the project and the buying price of the item: this is the actual cost of parts of the sub-project.',
'pf.dn' => 'Delivery note',
'pf.dn_w' => 'Warehouse — goods leave the building',
'pf.dn_q' => 'A numbered document for what leaves: to the project / vessel, to the customer, to production, or back to a supplier. Each line with an inventory item books its exit from the stock.',
'pf.dn_m' => 'No price on the document. The exit is valued like any issue, on the project it goes to.',
'pf.sinv' => 'Supplier invoice',
'pf.sinv_w' => 'Accounting — payables',
'pf.sinv_q' => 'Quantity invoiced per order line, checked against the quantity accepted at the receipt.',
'pf.sinv_m' => 'The payable: amount, due date, payment and its proof. A proforma of the supplier can be paid in advance and the invoice assigned later.',
'pf.cinv' => 'Proforma and payment of the customer',
'pf.cinv_w' => 'Sales · Accounting',
'pf.cinv_q' => '—',
'pf.cinv_m' => 'A proforma per payment term of the approved offer: issued, sent, partly paid, paid. This is the money that comes in.',
'pf.inv_title' => 'What changes the stock',
'pf.inv_1' => 'Receipt of a purchase order: in, at the price of the order.',
'pf.inv_2' => 'Approval of a requisition: free stock becomes reserved — on hand stays, free goes down.',
'pf.inv_3' => 'Issue to a project and delivery note: out, with the project on the movement.',
'pf.inv_4' => 'Parts used on a service report: out, on the project of the report.',
'pf.inv_5' => 'Manual movement by the warehouse: in, out, transfer between warehouses.',
'pf.inv_6' => 'Adjustment with its reason (stocktake, damaged, scrap, correction …) and the opening quantities of an import.',
'pf.dn_title' => 'Delivery notes',
'pf.dn_1' => 'Four kinds: to a project / vessel, to a customer, to production, return to a supplier.',
'pf.dn_2' => 'Made by the warehouse from Inventory › Delivery notes, or straight from what was received for a project and vessel.',
'pf.dn_3' => 'A line that comes from a requisition is booked as the issue of that requisition; any other item line as an exit of the stock.',
'pf.dn_4' => 'Cancelling a delivery note brings the quantities back into the stock and restores the reservation.',
'pf.dn_5' => 'The PDF carries recipient, address, carrier and reference — no prices.',
