'io.st_rej' => 'Отхвърлени',
'io.st_ot' => 'Одобрен извънреден труд',
'io.c_title' => 'Вход / Изход — записване на час и местоположение',
'io.c_text' => "Golden A/S записва часа и местоположението на телефона ви в момента, в който отбелязвате вход, и в момента, в който отбелязвате изход, заедно с най-близкия фирмен обект, точността на местоположението и използваното приложение или компютър. Местоположението ви не се следи между двете.\n\nДанните се използват за потвърждаване на присъствието на работното място, работното време и извънредния труд. Те се съпоставят с отчета ви за часове и сервизните ви доклади и се вземат предвид при оценката на персонала (постоянство и точност).\n\nЗаписите ви се виждат от HR, ръководството, вашия ръководител и ръководителите на проекти; статистиката — само от HR, изпълнителния директор и генералния мениджър. Собствените си записи виждате в приложението и в портала.\n\nПолитика за поверителност: https://www.goldenas.com.gr/privacy.html",
'io.c_accept' => 'Прочетох това уведомление и приемам записването на часа и местоположението на моя вход / изход.',
