'io.t_flow' => 'Процес',
'io.fl_lede' => 'Процедурата In / Out от първото приемане на уведомлението до оценката на персонала. Чете се отгоре надолу; двата странични клона на стъпка 3 са двата възможни резултата от автоматичната проверка.',
'io.fl_1t' => 'Прието уведомление',
'io.fl_1s' => 'веднъж, в приложението или в портала',
'io.fl_2t' => 'In',
'io.fl_2s' => 'приложение: час и позиция · портал: регистрирана мрежа',
'io.fl_3t' => 'Автоматична проверка',
'io.fl_3s' => 'обект · работно време · качество на позицията',
'io.fl_3lt' => 'Изключение — За решение',
'io.fl_3ls' => 'ръководител, проектен мениджър или HR одобрява или отхвърля',
'io.fl_3rt' => 'Изрядно',
'io.fl_3rs' => 'приема се автоматично',
'io.fl_4t' => 'Out',
'io.fl_4s' => 'същата проверка като при In',
'io.fl_5t' => 'Резултат за деня',
'io.fl_5s' => 'отработено време − почивка = нето · извънреден труд',
'io.fl_6t' => 'Кръстосана проверка',
'io.fl_6s' => 'разлика над {m} мин се показва',
'io.fl_6lt' => 'Timesheet',
'io.fl_6ls' => 'часове, записани за деня',
'io.fl_6rt' => 'Сервизни доклади',
'io.fl_6rs' => 'работно време (WT) за деня',
'io.fl_7t' => 'Решение за извънреден труд',
'io.fl_7s' => 'одобрен или отхвърлен, с бележка',
'io.fl_8t' => 'Статистика',
'io.fl_8s' => 'постоянство · точност · навреме',
'io.fl_9t' => 'Оценка на персонала',
'io.fl_9s' => 'постоянството се брои в «Присъствие и последователност»',
'io.fl_steps' => 'Стъпките с думи',
'io.fl_p1' => 'Уведомление. Първия път, когато използвате In / Out, прочитате уведомлението за записването на час и позиция и го приемате — веднъж, в приложението или в портала. Приемането се записва във вашия HR дневник. Без него не може да се регистрира запис.',
'io.fl_p2' => 'In. Когато започвате работа, натискате In. Приложението записва часа, позицията на телефона в този момент и най-близкия обект на фирмата. В портала In / Out работи само от регистриран мрежов адрес на обект на фирмата. Позицията ви не се следи между In и Out.',
'io.fl_p3' => 'Автоматична проверка. Всеки запис се проверява веднага: дали е в известен обект, в работното време (до {t} минути след началото се счита за навреме) и дали позицията е надеждна. Изряден запис се приема автоматично. Запис със забележка — извън обект, закъснение, по-рано, слаба или липсваща позиция, Out без In, двоен запис — е изключение: чака в «За решение», докато вашият ръководител, проектен мениджър или HR го одобри или отхвърли с бележка.',
'io.fl_p4' => 'Out. Когато приключвате работа, натискате Out. Минава същата проверка като In. Допускат се няколко двойки In / Out в един ден (например посещение на кораб и връщане в офиса).',
'io.fl_p5' => 'Резултат за деня. Порталът събира времето между всеки In и неговия Out. В работен ден от пет часа или повече се изважда почивката от вашия календар на работното време. Това, което надвишава планираните часове, е извънреден труд, когато е поне {o} минути; цялото време в неработен ден е извънреден труд.',
'io.fl_p6' => 'Кръстосана проверка. Нетното време за деня се сравнява с часовете, записани във вашия timesheet, и с работното време (WT) в сервизните доклади за същия ден. Разлика над {m} минути спрямо timesheet в едната или другата посока, или повече работно време в сервизните доклади, отколкото показва присъствието, се отбелязва в «Извънреден труд и съпоставка», за да се коригира timesheet, докладът или записът.',
'io.fl_p7' => 'Решение за извънреден труд. Извънредният труд не се приема сам. Лицето, което решава за вашите записи, го одобрява или отхвърля по дни, с бележка. Отхвърлените записи не се броят в резултата за деня.',
'io.fl_p8' => 'Статистика. За всеки човек HR, изпълнителният директор и генералният мениджър виждат три показателя за период: постоянство (работни дни с пълни In и Out), точност (записи без забележка) и навреме (първи In за деня в рамките на толеранса).',
'io.fl_p9' => 'Оценка на персонала. Постоянството за годината е част от изчислената оценка «Присъствие и последователност» на годишната оценка; точността и делът навреме се показват до нея, на оценяващия и на вас в My HR.',
'io.fl_ev_h' => 'Връзка с оценката на персонала',
'io.fl_ev_p1' => 'Годишната оценка има два критерия, изчислявани от портала. «Присъствие и последователност» започва от 5 и губи точки за ранни тръгвания и закъснения, непланирани отсъствия и отпуск, поискан в последния момент (от одобрените HR заявки за годината), и за постоянството на In / Out.',
'io.fl_ev_p2' => 'Постоянство In / Out = дни с пълни In и Out ÷ очаквани дни. Очаквани са работните дни от вашия календар от първия ви запис за годината до днес; дните на одобрен отпуск, болнични или отсъствие без запис се изключват. От 90 % не се приспада нищо; под това — една точка за всеки започнати десет процентни пункта (80–89 %: −1, 70–79 %: −2, по-ниско: −3). При по-малко от 20 очаквани дни показателят се показва и още не се оценява. Процентът на първия праг се задава в Обекти и правила.',
'io.fl_ev_p3' => 'Точността и делът навреме се показват под критерия и не променят оценката. Виждате своите показатели в My HR › Как ви оценяваме.',
'io.ev_txt' => 'In / Out за годината: постоянство {c} ({d} от {w} очаквани дни; {x} ден/дни одобрен отпуск или отсъствие са изключени) · точност {a} · навреме {p} — {s}',
'ft.title' => 'Кошче',
'ft.lede' => 'Файловете, премахнати от потребителите, се пазят тук {d} дни. Дотогава администратор може да възстанови файл на мястото, откъдето е дошъл, или да го премахне окончателно. След {d} дни порталът го премахва окончателно сам.',
