'ft.rule_2' => 'Файл може да бъде премахнат от този, който го е качил, от проектния мениджър на проекта му и от администраторите.',
'ft.rule_3' => 'Издадените документи, изпратените оферти и приложенията им, подписаните сервизни и инспекционни доклади и фактурите на доставчици са защитени: премахва ги само администратор, с писмена причина.',
