'pdc.xl_tpl_n7' => 'До {max} реда и 2 MB. Без формули, суми или обединени клетки; един и същ код може да е на няколко реда. Приемат се и гръцките заглавия на документа: Κωδικός, Περιγραφή, Ποσότητα, Μ.Μ., Τιμή, Εκπτ.%, Καθαρή αξία.',
